import React from "react"
import dayjs from "dayjs"
import {
    Bar,
    BarChart,
    CartesianGrid,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
} from "recharts"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * `AiQuotaHistoryPanel` — the "History" tab body inside `AiQuotaModal`: a 7-day
 * usage bar chart plus a scrollable, bordered list of recent AI charges.
 * `isLoading` swaps the whole `ChargesList` region for its shimmer mirror; an
 * empty `items` array renders the list's own empty state. The chart draws from
 * `chartPoints` regardless of either.
 */

/** What an AI charge was for — the block owns the display label per surface. */
export type AiQuotaHistorySurface = "grade" | "interview" | "chatbot"

/** {@link AiQuotaHistorySurface} → its display label. The block's own vocabulary (§14d.1). */
const PURPOSE_LABEL: Record<AiQuotaHistorySurface, string> = {
    grade: "Challenge grading",
    interview: "Interview grading",
    chatbot: "AI chat",
}

/** Fallback row title when a charge carries no specific model name. */
const AUTO_MODEL_LABEL = "Automatic model (free)"

/** Unit suffix on every credit-delta chip. */
const CREDITS_UNIT = "credit"

/** One day-bucket plotted on the usage chart. */
export interface AiQuotaHistoryChartPoint {
    /** X-axis label, already formatted (e.g. `"12/07"`). */
    day: string
    /** Credits consumed that day. */
    credits: number
}

/** One row of the recent-charges list. */
export interface AiQuotaHistoryChargeItem {
    /** Stable React key. */
    key: string
    /** Model name, when the charge names one specifically. Falls back to {@link AUTO_MODEL_LABEL}. */
    model?: string
    /** What the charge was for — drives the block-owned {@link PURPOSE_LABEL}. */
    surface: AiQuotaHistorySurface
    /** When the charge happened — the block formats this itself (`HH:mm DD/MM`). */
    occurredAt: string | number | Date
    /** Credit delta for this charge. Sign drives the trailing chip's tone (see judgement call 4). */
    credits: number
}

/** Props for {@link AiQuotaHistoryPanel}. */
export interface AiQuotaHistoryPanelProps {
    /** The 7 day-buckets for the chart. Defaults to an empty plot when omitted. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running (drives ONLY the `ChargesList` leaf). */
    isLoading: boolean
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
}

/** How many placeholder rows the loading mirror shows — matches the source's 3-row skeleton. */
const SKELETON_ROW_COUNT = 3

/** Chip tone for a credit delta — see judgement call 4 in the file header: ported verbatim. */
const deltaTone = (credits: number): ChipTone => (credits > 0 ? "warning" : "success")

const toListItem = (item: AiQuotaHistoryChargeItem): SurfaceCardListItem => ({
    key: item.key,
    title: item.model ?? AUTO_MODEL_LABEL,
    subtitle: `${PURPOSE_LABEL[item.surface]} · ${dayjs(item.occurredAt).format("HH:mm DD/MM")}`,
    meta: () => <Chip tone={deltaTone(item.credits)} text={`${item.credits} ${CREDITS_UNIT}`} />,
})

/** Placeholder rows for the loading mirror — same row shape, shimmer chip in the meta slot. */
const skeletonItems = (): Array<SurfaceCardListItem> => Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => ({
    key: `skeleton-${index}`,
    title: "Model",
    subtitle: "Purpose · Time",
    meta: () => <Chip isSkeleton />,
}))

/**
 * History tab body of `AiQuotaModal` — usage chart + recent-charges list.
 *
 * @param props - {@link AiQuotaHistoryPanelProps}
 */
export const AiQuotaHistoryPanel = ({
    chartPoints = [],
    items,
    isLoading,
}: AiQuotaHistoryPanelProps) => {
    const isEmpty = !isLoading && (items?.length ?? 0) === 0

    const chart = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => <Typography size="sm" weight="medium" text="Credits used per day (last 7 days)" />,
                () => (
                    <SurfaceCard
                        variant="nested"
                        padding={4}

                        body={() => (
                            <div className="h-44 w-full text-accent-soft-foreground">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={chartPoints} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                        <CartesianGrid
                                            strokeDasharray="3 3"
                                            stroke="currentColor"
                                            className="text-divider"
                                            vertical={false}
                                        />
                                        <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={0} tickLine={false} axisLine={false} />
                                        <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                        <Tooltip
                                            cursor={{ fill: "currentColor", opacity: 0.08 }}
                                            formatter={(value) => [`${value} ${CREDITS_UNIT}`, ""]}
                                        />
                                        <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                    />
                ),
            ]} />
    )

    const chargesList = (
        <StackV gap={4} items={[
            () => <Typography size="sm" weight="medium" text="AI usage history" />,
            () => (
                <div className="max-h-64 overflow-y-auto">
                    <AsyncContent
                        isLoading={isLoading}
                        skeleton={() => <SurfaceCardList variant="nested" items={skeletonItems()} isSkeleton />}
                        isEmpty={isEmpty}
                        emptyContent={{
                            title: "No AI usage yet.",

                        }}
                        content={() => <SurfaceCardList variant="nested" items={(items ?? []).map((item) => toListItem(item))} />}

                    />
                </div>
            ),
        ]} />
    )

    return (
        <StackV
            identity={{ tier: "block", component: "AiQuotaHistoryPanel" }}
            gap={6}
            items={[() => chart, () => chargesList]}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Button, Popover } from "@heroui/react"
import { useTranslations } from "next-intl"
import { REACTION_BY_TYPE } from "./constants"
import { ReactionEmoji } from "./ReactionEmoji"
import { FacebookReactionSelector } from "./FacebookReactionSelector"
import { ReactionType, type ReactionSummary } from "@/modules/api/graphql/queries/types/discussion"

/** Props for {@link ReactionBar}. */
export interface ReactionBarProps {
    /** Current reaction summary for the target (content or comment). */
    summary: ReactionSummary | undefined
    /** Called with a new emotion, or null to remove the current one. */
    onReact: (type: ReactionType | null) => void
    /** Disables interaction (e.g. while a mutation is in flight). */
    disabled?: boolean
}

/**
 * Facebook-style reaction control: a HeroUI Button trigger that opens a 6-emoji picker
 * (HeroUI Popover), plus a compact summary (top emojis + total). Picking the active
 * emotion again removes it. The SAME control is used for both the content reaction
 * (InteractionBar) and each comment, so they render identically.
 *
 * Presentational: only local picker-open state; all persistence is delegated via `onReact`.
 * @param props - {@link ReactionBarProps}
 */
export const ReactionBar = ({ summary, onReact, disabled}: ReactionBarProps) => {
    const t = useTranslations()
    // controlled so the popover closes as soon as an emotion is picked
    const [open, setOpen] = useState(false)
    const myReaction = summary?.myReaction ?? null
    const total = summary?.total ?? 0
    // emotions present on the target, busiest first, capped to the top 3 descriptors
    const topReactions = (summary?.counts ?? [])
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((count) => REACTION_BY_TYPE[count.type])
        .filter(Boolean)

    const myDescriptor = myReaction ? REACTION_BY_TYPE[myReaction] : REACTION_BY_TYPE[ReactionType.Like]

    // picking an emotion toggles it off when it's already the user's pick, then closes
    const handlePick = (type: ReactionType) => {
        setOpen(false)
        onReact(myReaction === type ? null : type)
    }

    return (
        <div className={"flex items-center gap-2"}>
            {/* trigger: a real HeroUI Button (pill); secondary once the viewer has reacted */}
            <Popover isOpen={open} onOpenChange={setOpen}>
                <Popover.Trigger>
                    <Button
                        size="sm"
                        variant={myReaction ? "secondary" : "tertiary"}
                        isDisabled={disabled}
                        className="rounded-full"
                    >
                        <ReactionEmoji descriptor={myDescriptor} size="xs" />
                        <span className="text-xs">
                            {myReaction
                                ? t(REACTION_BY_TYPE[myReaction].labelKey)
                                : t("discussion.react")}
                        </span>
                    </Button>
                </Popover.Trigger>
                <Popover.Content className="overflow-visible rounded-full px-2 py-1">
                    <FacebookReactionSelector active={myReaction} onSelect={handlePick} />
                </Popover.Content>
            </Popover>

            {/* compact summary: stacked top emojis + total count */}
            {total > 0 ? (
                <div className="flex items-center gap-2 text-xs text-muted">
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionEmoji key={reaction.type} descriptor={reaction} size="xs" />
                        ))}
                    </span>
                    <span>{total}</span>
                </div>
            ) : null}
        </div>
    )
}

import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** A reaction kind's emoji + Facebook Emoji type + i18n label key. */
export interface ReactionDescriptor {
    /** The reaction kind. */
    type: ReactionType
    /** Native emoji glyph (fallback / alt text). */
    emoji: string
    /**
     * The `type` prop value for the `react-facebook-emoji` `FacebookEmoji` component.
     * Maps each ReactionType to the library's lowercase string.
     */
    fbType: "like" | "love" | "haha" | "wow" | "sad" | "angry" | "yay"
    /** i18n key under `discussion.reactions.*` for the accessible label. */
    labelKey: string
}

/** Ordered list of supported reactions (Facebook-style), driving the picker + summary. */
export const REACTIONS: ReadonlyArray<ReactionDescriptor> = [
    {
        type: ReactionType.Like,
        emoji: "👍",
        fbType: "like",
        labelKey: "discussion.reactions.like",
    },
    {
        type: ReactionType.Love,
        emoji: "❤️",
        fbType: "love",
        labelKey: "discussion.reactions.love",
    },
    {
        type: ReactionType.Haha,
        emoji: "😂",
        fbType: "haha",
        labelKey: "discussion.reactions.haha",
    },
    {
        type: ReactionType.Wow,
        emoji: "😮",
        fbType: "wow",
        labelKey: "discussion.reactions.wow",
    },
    {
        type: ReactionType.Sad,
        emoji: "😢",
        fbType: "sad",
        labelKey: "discussion.reactions.sad",
    },
    {
        type: ReactionType.Angry,
        emoji: "😡",
        fbType: "angry",
        labelKey: "discussion.reactions.angry",
    },
]

/** Quick lookup from reaction type → descriptor. */
export const REACTION_BY_TYPE: Record<ReactionType, ReactionDescriptor> = REACTIONS.reduce(
    (acc, descriptor) => {
        acc[descriptor.type] = descriptor
        return acc
    },
    {} as Record<ReactionType, ReactionDescriptor>,
)

"use client"

import React from "react"
import {
    cn,
    Separator,
    Skeleton,
} from "@heroui/react"
import {
    SkeletonText,
} from "../SkeletonText"
import type {
    AccordionSkeletonProps,
} from "./types"

/**
 * Static accordion-shaped loading placeholder — no HeroUI `Accordion` (no expand/collapse logic).
 * Mirrors title row + optional chevron + expanded body so layout stays stable when real accordion mounts.
 * @param props - {@link AccordionSkeletonProps}
 */
export const AccordionSkeleton = (props: AccordionSkeletonProps) => {
    const {
        items,
        className,
        renderExpandedBody,
    } = props
    return (
        <div
            className={cn("rounded-none border-none px-0 shadow-none", className)}
            aria-busy="true"
        >
            {
                items.map(
                    (item, index) => {
                        const showIndicator = item.showIndicator !== false
                        const titleSize = item.titleSize ?? "base"
                        return (
                            <React.Fragment key={index}>
                                <div
                                    aria-label={item.ariaLabel}
                                >
                                    <div className="flex w-full items-center justify-between gap-2 p-3">
                                        <SkeletonText
                                            size={titleSize}
                                            width={item.titleWidth}
                                            className="min-w-0 flex-1"
                                        />
                                        {showIndicator ? (
                                            <Skeleton className="w-5 h-5 rounded-full" />
                                        ) : null}
                                    </div>
                                    {
                                        item.expanded && renderExpandedBody ? (
                                            <div className="rounded-none border-none p-3 pt-2">
                                                {renderExpandedBody(index)}
                                            </div>
                                        ) : null
                                    }
                                </div>
                                <Separator className="last:hidden" />
                            </React.Fragment>
                        )
                    }
                )
            }
        </div>
    )
}

"use client"

import React from "react"
import {
    SkeletonText,
    type SkeletonTextSize,
} from "../SkeletonText"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Stepped widths cycled across paragraph lines so the block reads like real
 * prose (full lines with a shorter trailing line) instead of a solid rectangle.
 * Default 3-line progression reads 100% → 75% → 50%.
 */
const stepWidths = ["w-full", "w-3/4", "w-1/2"] as const

/** Props for {@link SkeletonParagraph}. */
export interface SkeletonParagraphProps extends WithClassNames<undefined> {
    /** Typography token shared by every line; drives each bar's height. */
    size: SkeletonTextSize
    /** Number of skeleton lines to render. Defaults to `3`. */
    lines?: number
}

/**
 * A multi-line text skeleton: renders `lines` {@link SkeletonText} bars with
 * stepped, decreasing widths so the final line reads shorter, mimicking a real
 * paragraph.
 * @param props - {@link SkeletonParagraphProps}
 */
export const SkeletonParagraph = (props: SkeletonParagraphProps) => {
    const {
        size,
        lines = 3,
        className,
    } = props
    return (
        <div className={className}>
            {Array.from({ length: Math.max(lines, 0) }).map((_unused, index) => {
                // Last line is always the shortest; earlier lines cycle the
                // stepped widths so long paragraphs keep a natural rhythm.
                const isLast = index === lines - 1
                const width = isLast
                    ? stepWidths[stepWidths.length - 1]
                    : stepWidths[Math.min(index, stepWidths.length - 2)]
                return (
                    <SkeletonText
                        key={index}
                        size={size}
                        width={width}
                    />
                )
            })}
        </div>
    )
}

"use client"

import React from "react"
import {
    Skeleton,
    cn,
} from "@heroui/react"
import {
    skeletonTextSizeMap,
} from "./map"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Typography token of the text the skeleton bar stands in for. Each token maps
 * to a Tailwind `text-*` size and resolves (via {@link skeletonTextSizeMap}) to
 * the height + vertical margin that reproduces the real text's line-box, so the
 * layout does not shift when data arrives.
 */
export type SkeletonTextSize =
    /** Mirrors `text-xs` (12px). */
    | "xs"
    /** Mirrors `text-sm` (14px). */
    | "sm"
    /** Mirrors `text-base` (16px). */
    | "base"
    /** Mirrors `text-lg` (18px). */
    | "lg"
    /** Mirrors `text-xl` (20px). */
    | "xl"
    /** Mirrors `text-2xl` (24px). */
    | "2xl"
    /** Mirrors `text-3xl` (30px). */
    | "3xl"
    /** Mirrors `text-4xl` (36px). */
    | "4xl"
    /** Mirrors `text-5xl` (48px). */
    | "5xl"
    /** Mirrors `text-6xl` (60px). */
    | "6xl"

/** Props for {@link SkeletonText}. */
export interface SkeletonTextProps extends WithClassNames<undefined> {
    /** Typography token of the text being replaced; drives the bar's height. */
    size: SkeletonTextSize
    /** Tailwind width class for the bar (e.g. `"w-5/6"`). Defaults to `"w-full"`. */
    width?: string
}

/**
 * A single-line text skeleton that occupies the exact line-box of the real text
 * it replaces. Corner radius is derived from `size` via {@link skeletonTextSizeMap}
 * (xs/sm → `rounded-sm`; base and above → `rounded`).
 * @param props - {@link SkeletonTextProps}
 */
export const SkeletonText = (props: SkeletonTextProps) => {
    const {
        size,
        width = "w-full",
        className,
    } = props
    return (
        <Skeleton
            className={
                cn(
                    skeletonTextSizeMap[size],
                    width,
                    className,
                )
            }
        />
    )
}

import React from "react"
import { Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SkeletonAccordion}. */
export interface SkeletonAccordionProps extends WithClassNames<undefined> {
    /** Number of accordion items. Defaults to 3. */
    items?: number
}

/**
 * Skeleton matching a HeroUI <Accordion variant="surface"/>: KEEPS the surface
 * shell (rounded-3xl bg-surface — rule: surface blocks like Card/Accordion keep
 * their surface in the skeleton, only inner content becomes bars). Each item is a
 * trigger row (px-4 py-4 + text-sm/leading-6 -> h-14 box) followed by a 1px
 * separator (the last item has no separator, matching :last-child::after { none }).
 */
export const SkeletonAccordion = ({
    className,
    items = 3,
}: SkeletonAccordionProps) => {
    return (
        <div className={cn("w-full overflow-hidden rounded-3xl bg-surface", className)}>
            {Array.from({ length: items }).map((_, index) => (
                <div key={index} className="relative">
                    {/* Trigger row (h-14): label bar + indicator */}
                    <div className="flex h-14 items-center justify-between px-4">
                        <Skeleton className="my-[5px] h-[14px] w-2/5 rounded" />
                        <Skeleton className="size-4 rounded" />
                    </div>
                    {/* Separator (h-px), omitted on the last item */}
                    {index < items - 1 && (
                        <Skeleton className="h-px w-full rounded-xs" />
                    )}
                </div>
            ))}
        </div>
    )
}

/** Folder-matching alias (export-matches-folder) — keep `SkeletonAccordion` as the public name. */
export { SkeletonAccordion as Accordion }

import React from "react"
import { Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Avatar size matching HeroUI <Avatar/> (sm=size-8/md=size-10/lg=size-12). */
export type SkeletonAvatarSize = "sm" | "md" | "lg"

/** Props for {@link SkeletonAvatar}. */
export interface SkeletonAvatarProps extends WithClassNames<undefined> {
    /** Avatar size; mirrors HeroUI Avatar sizes. Defaults to "md". */
    size?: SkeletonAvatarSize
}

const SIZE_CLASS: Record<SkeletonAvatarSize, string> = {
    sm: "size-8",
    md: "size-10",
    lg: "size-12",
}

/** Skeleton matching a HeroUI <Avatar/> box (square, circular shape). */
export const SkeletonAvatar = ({ size = "md", className }: SkeletonAvatarProps) => {
    return <Skeleton className={cn("rounded-full", SIZE_CLASS[size], className)} />
}

/** Folder-matching alias (export-matches-folder) — keep `SkeletonAvatar` as the public name. */
export { SkeletonAvatar as Avatar }

import React from "react"
import { Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SkeletonBadge} — no part-specific props; the small badge is a fixed square dot. */
export type SkeletonBadgeProps = WithClassNames<undefined>

/**
 * Skeleton matching a HeroUI <Badge/> box (small size).
 * Badge --sm: min-h-4 min-w-4 → 16px square, circular shape.
 */
export const SkeletonBadge = ({ className }: SkeletonBadgeProps) => {
    return <Skeleton className={cn("size-4 rounded-full", className)} />
}

/** Folder-matching alias (export-matches-folder) — keep `SkeletonBadge` as the public name. */
export { SkeletonBadge as Badge }

import React from "react"
import { Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SkeletonBreadcrumbs}. */
export interface SkeletonBreadcrumbsProps extends WithClassNames<undefined> {
    /** Number of breadcrumb crumbs. Defaults to 3. */
    count?: number
}

/**
 * Skeleton matching a HeroUI <Breadcrumbs/>: count crumb bars
 * (link text-sm/leading-5 -> h-[14px] my-[3px]) interleaved with size-3
 * separator icons.
 */
export const SkeletonBreadcrumbs = ({
    className,
    count = 3,
}: SkeletonBreadcrumbsProps) => {
    return (
        <div className={cn("flex items-center", className)}>
            {Array.from({ length: count }).map((_, index) => (
                <React.Fragment key={index}>
                    {/* Crumb item wrapper */}
                    <div className="flex shrink-0 items-center">
                        <Skeleton className="my-[3px] h-[14px] w-16 rounded" />
                    </div>
                    {/* Separator (size-3), omitted after the last crumb */}
                    {index < count - 1 && (
                        <Skeleton className="size-3 rounded-xs" />
                    )}
                </React.Fragment>
            ))}
        </div>
    )
}

/** Folder-matching alias (export-matches-folder) — keep `SkeletonBreadcrumbs` as the public name. */
export { SkeletonBreadcrumbs as Breadcrumbs }

import React from "react"
import { Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SkeletonButton}. */
export interface SkeletonButtonProps extends WithClassNames<undefined> {
    /** Full Tailwind width class, e.g. "w-24" or "w-full". Defaults to "w-24". */
    width?: string
}

/**
 * Skeleton matching a HeroUI <Button/> box.
 * Button is h-10 on mobile / @app-md:h-9 (36px) with rounded-3xl — a full pill at this height.
 */
export const SkeletonButton = ({ className, width = "w-24" }: SkeletonButtonProps) => {
    return <Skeleton className={cn("h-10 @app-md:h-9 rounded-full", width, className)} />
}

/** Folder-matching alias (export-matches-folder) — keep `SkeletonButton` as the public name. */
export { SkeletonButton as Button }

import React from "react"
import { Card, CardContent, Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SkeletonCard}. */
export interface SkeletonCardProps extends WithClassNames<undefined> {
    /** Number of body block lines. Defaults to 3. */
    lines?: number
}

/**
 * Skeleton matching a HeroUI <Card/>: renders the REAL `Card` + `CardContent`
 * frame (border/radius/padding baked in) wrapping a title bar (body-sm 14px) over
 * body lines (body-xs 12px), so the loading box shares the card's exact footprint.
 */
export const SkeletonCard = ({ className, lines = 3 }: SkeletonCardProps) => (
    <Card className={className}>
        <CardContent className="flex flex-col gap-2">
            {/* Title (body-sm) */}
            <Skeleton className="my-[5px] h-[14px] w-1/2 rounded" />
            {/* Body lines (body-xs) */}
            {Array.from({ length: lines }).map((_, index) => (
                <Skeleton
                    key={index}
                    className={cn("h-3 rounded", index === lines - 1 ? "w-2/3" : "w-full")}
                />
            ))}
        </CardContent>
    </Card>
)

/** Folder-matching alias (export-matches-folder) — keep `SkeletonCard` as the public name. */
export { SkeletonCard as Card }

import React from "react"
import { Skeleton, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link SkeletonCheckbox}. */
export interface SkeletonCheckboxProps extends WithClassNames<undefined> {
    /** Render the label line next to the box. Defaults to true. */
    withLabel?: boolean
    /** Full Tailwind width class for the label bar, e.g. "w-32". Defaults to "w-32". */
    labelWidth?: string
}

/**
 * Skeleton matching a HeroUI <Checkbox/>.
 * Control is size-4 (16px) rounded-md; the label uses text-sm (body-sm 14/24),
 * so the label bar is the 14px glyph height centered in its 24px box (my-[5px]).
 * Row is gap-3 to match the checkbox label gap.
 */
export const SkeletonCheckbox = ({
