                    items={[
                        () => (
                            <TabsCard
                                variant="primary"
                                leftTabs={{
                                    selectedKey: applyMethod,
                                    ariaLabel: t("jobs.post.applyMethod.toggleAria"),
                                    onSelectionChange: (key) => setValue("applyMethod", String(key) as JobApplyMethod),
                                    items: [
