                            </TextField>
                        )),
                    ]} />
            )}
        />
    )
}

"use client"

import React, { useEffect, useState } from "react"
import { Button, Input, Label, TextField, Typography } from "@heroui/react"
import { XIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { UseFormSetValue } from "react-hook-form"
import { useQueryHeadhuntingCompanySuggestionsSwr } from "@/hooks/swr/api/graphql/queries/useQueryHeadhuntingCompanySuggestionsSwr"
import type { SubmitJobPostingFormValues } from "@/hooks/rhf/useSubmitJobPostingForm"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Debounce window (ms) before a typed search hits the suggestions backend. */
const SEARCH_DEBOUNCE_MS = 350
/** Max length of a new-company title (mirrors the `title` column cap used elsewhere). */
const COMPANY_TITLE_MAX = 255

/** Props for {@link CompanySection}. */
export interface CompanySectionProps {
    /** Chosen existing company id (empty = none picked yet). */
    companyId: string
    /** Chosen existing company's display label. */
    companyLabel: string
    /** New-company field values (used when no existing company is picked). */
    newCompanyTitle: string
    newCompanyLogoUrl: string
    newCompanyWebsiteUrl: string
    /** Sets a single form field. */
    setValue: UseFormSetValue<SubmitJobPostingFormValues>
}

/**
 * "Company" section of the job-post form: an ES-backed company typeahead to pick
 * an EXISTING {@link import("@/modules/types/entities/headhunting-company").HeadhuntingCompanyEntity},
 * or — when nothing is picked — a fallback set of fields to register a brand-new
 * company inline. Exactly one of the two paths feeds `submitJobPosting` (enforced
 * in {@link import("@/hooks/rhf/useSubmitJobPostingForm").useSubmitJobPostingForm}).
 *
 * @param props - {@link CompanySectionProps}
 */
export const CompanySection = ({
    companyId,
    companyLabel,
    newCompanyTitle,
    newCompanyLogoUrl,
    newCompanyWebsiteUrl,
    setValue,
}: CompanySectionProps) => {
    const t = useTranslations()

    const [query, setQuery] = useState("")
    const [debouncedQuery, setDebouncedQuery] = useState("")
    useEffect(() => {
        const handle = setTimeout(() => setDebouncedQuery(query), SEARCH_DEBOUNCE_MS)
        return () => clearTimeout(handle)
    }, [query])

    const { data: suggestionItems } = useQueryHeadhuntingCompanySuggestionsSwr(debouncedQuery)
    const suggestions = suggestionItems ?? []

    const hasPickedCompany = Boolean(companyId)

    return (
        <SurfaceCard
            label={t("jobs.post.sections.company")}

            body={() => (
                <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => (hasPickedCompany ? (
                            <Box principle="row-pad" className="rounded-2xl border border-default px-4 py-3"
                                explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                                <StackH gap={4} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    justify="between" align="center" items={[
                                        () => (
                                            <Typography type="body-sm" weight="medium">
                                                {companyLabel}
                                            </Typography>
                                        ),
                                        () => (
                                            <Button
                                                variant="tertiary"
                                                size="sm"
                                                onPress={() => {
                                                    setValue("companyId", "")
                                                    setValue("companyLabel", "")
                                                    setQuery("")
                                                }}
                                            >
                                                <XIcon aria-hidden focusable="false" className="size-4" />
                                                {t("jobs.post.company.change")}
                                            </Button>
                                        ),
                                    ]} />
                            </Box>
                        ) : (
                            <StackV gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => (
                                        <SearchInput
                                            value={query}
                                            onValueChange={setQuery}
                                            placeholder={t("jobs.post.company.searchPlaceholder")}
                                            suggestions={suggestions}
                                            onSelectSuggestion={(suggestion) => {
                                                setValue("companyId", suggestion.id)
                                                setValue("companyLabel", suggestion.label)
                                                setQuery("")
                                            }}
                                        />
                                    ),
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("jobs.post.company.notFoundHint")}
                                        </Typography>
                                    ),
                                    () => (
                                        <Box principle="separator-dot" className="border-t border-default pt-3"
                                            explain="Places a middle-dot separator between short meta peers so the items read as one inline list.">
                                            <StackV gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-new-company-title">
                                                                {t("jobs.post.company.newTitle")}
                                                            </Label>
                                                            <Input
                                                                id="job-post-new-company-title"
                                                                placeholder={t("jobs.post.company.newTitlePlaceholder")}
                                                                maxLength={COMPANY_TITLE_MAX}
                                                                value={newCompanyTitle}
                                                                onChange={(event) => setValue("newCompanyTitle", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                    () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-new-company-logo">
                                                                {t("jobs.post.company.newLogoUrl")}
                                                            </Label>
                                                            <Input
                                                                id="job-post-new-company-logo"
                                                                type="url"
                                                                placeholder={t("jobs.post.company.newLogoUrlPlaceholder")}
                                                                value={newCompanyLogoUrl}
                                                                onChange={(event) => setValue("newCompanyLogoUrl", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                    () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-new-company-website">
                                                                {t("jobs.post.company.newWebsiteUrl")}
                                                            </Label>
                                                            <Input
                                                                id="job-post-new-company-website"
                                                                type="url"
                                                                placeholder={t("jobs.post.company.newWebsiteUrlPlaceholder")}
                                                                value={newCompanyWebsiteUrl}
                                                                onChange={(event) => setValue("newCompanyWebsiteUrl", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                ]} />
                                        </Box>
                                    ),
                                ]} />
                        )),
                    ]} />
            )}
        />
    )
}

"use client"

import React from "react"
import {
    Input,
    Label,
    ListBox,
    Select,
    TextArea,
    TextField,
    Typography,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import type { UseFormSetValue } from "react-hook-form"
import type { SubmitJobPostingFormValues } from "@/hooks/rhf/useSubmitJobPostingForm"
import { JobEmploymentType } from "@/modules/types/enums/job-employment-type"
import { WorkMode } from "@/modules/types/enums/work-mode"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Grid } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"

/** Max length of the job title. */
const TITLE_MAX = 255
/** Max length of the free-text location. */
const LOCATION_MAX = 100
/** Sentinel key for "no selection" in the employment-type / work-mode selects. */
const NONE_KEY = "none"

/** Employment-type options + their i18n label keys. */
const EMPLOYMENT_TYPE_OPTIONS = [
    { value: JobEmploymentType.Fulltime, labelKey: "jobs.employmentType.fulltime" },
    { value: JobEmploymentType.Parttime, labelKey: "jobs.employmentType.parttime" },
    { value: JobEmploymentType.Internship, labelKey: "jobs.employmentType.internship" },
    { value: JobEmploymentType.Contract, labelKey: "jobs.employmentType.contract" },
] as const

/** Work-mode options + their i18n label keys (reuses the existing profile labels). */
const WORK_MODE_OPTIONS = [
    { value: WorkMode.Remote, labelKey: "publicProfile.workMode.remote" },
    { value: WorkMode.Hybrid, labelKey: "publicProfile.workMode.hybrid" },
    { value: WorkMode.Onsite, labelKey: "publicProfile.workMode.onsite" },
] as const

/** Props for {@link PositionSection}. */
export interface PositionSectionProps {
    title: string
    employmentType: JobEmploymentType | ""
    workMode: WorkMode | ""
    location: string
    salaryMin: string
    salaryMax: string
    description: string
    requirements: string
    /** Sets a single form field. */
    setValue: UseFormSetValue<SubmitJobPostingFormValues>
}

/**
 * "Position" section of the job-post form — title, employment type,
 * work mode, location, salary range (blank + blank = negotiable), and the
 * markdown description / requirements.
 *
 * @param props - {@link PositionSectionProps}
 */
export const PositionSection = ({
    title,
    employmentType,
    workMode,
    location,
    salaryMin,
    salaryMax,
    description,
    requirements,
    setValue,
}: PositionSectionProps) => {
    const t = useTranslations()

    return (
        <SurfaceCard
            label={t("jobs.post.sections.position")}

            body={() => (
                <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-title">{t("jobs.post.position.title")}</Label>
                                <Input
                                    id="job-post-title"
                                    placeholder={t("jobs.post.position.titlePlaceholder")}
                                    maxLength={TITLE_MAX}
                                    value={title}
                                    onChange={(event) => setValue("title", event.target.value)}
                                />
                            </TextField>
                        ),

                        () => (
                            <Grid columns={{ base: 1, sm: 2 }} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    {
                                        key: "employment-type",
                                        content: () => (
                                            <StackV gap={3} principle="label-field"
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Label htmlFor="job-post-employment-type">{t("jobs.post.position.employmentType")}</Label>,
                                                    () => (
                                                        <Select.Root<{ id: string }, "single">
                                                            id="job-post-employment-type"
                                                            aria-label={t("jobs.post.position.employmentType")}
                                                            selectedKey={employmentType === "" ? NONE_KEY : employmentType}
                                                            onSelectionChange={(key) =>
                                                                setValue(
                                                                    "employmentType",
                                                                    key === NONE_KEY ? "" : (String(key) as JobEmploymentType),
                                                                )
                                                            }
                                                        >
                                                            <Select.Trigger aria-label={t("jobs.post.position.employmentType")}>
                                                                <Select.Value>
                                                                    {() => {
                                                                        const found = EMPLOYMENT_TYPE_OPTIONS.find(
                                                                            (option) => option.value === employmentType,
                                                                        )
                                                                        return (
                                                                            <Typography type="body-sm">
                                                                                {found ? t(found.labelKey) : t("jobs.post.position.employmentTypeNone")}
                                                                            </Typography>
                                                                        )
                                                                    }}
                                                                </Select.Value>
                                                                <Select.Indicator />
                                                            </Select.Trigger>
                                                            <Select.Popover>
                                                                <ListBox.Root aria-label={t("jobs.post.position.employmentType")}>
                                                                    <ListBox.Item id={NONE_KEY} textValue={t("jobs.post.position.employmentTypeNone")}>
                                                                        {t("jobs.post.position.employmentTypeNone")}
                                                                    </ListBox.Item>
                                                                    {EMPLOYMENT_TYPE_OPTIONS.map((option) => (
                                                                        <ListBox.Item key={option.value} id={option.value} textValue={t(option.labelKey)}>
                                                                            {t(option.labelKey)}
                                                                        </ListBox.Item>
                                                                    ))}
                                                                </ListBox.Root>
                                                            </Select.Popover>
                                                        </Select.Root>
                                                    ),
                                                ]} />
                                        ),
                                    },

                                    {
                                        key: "work-mode",
                                        content: () => (
                                            <StackV gap={3} principle="label-field"
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Label htmlFor="job-post-work-mode">{t("jobs.post.position.workMode")}</Label>,
                                                    () => (
                                                        <Select.Root<{ id: string }, "single">
                                                            id="job-post-work-mode"
                                                            aria-label={t("jobs.post.position.workMode")}
                                                            selectedKey={workMode === "" ? NONE_KEY : workMode}
                                                            onSelectionChange={(key) =>
                                                                setValue("workMode", key === NONE_KEY ? "" : (String(key) as WorkMode))
                                                            }
                                                        >
                                                            <Select.Trigger aria-label={t("jobs.post.position.workMode")}>
                                                                <Select.Value>
                                                                    {() => {
                                                                        const found = WORK_MODE_OPTIONS.find(
                                                                            (option) => option.value === workMode,
                                                                        )
                                                                        return (
                                                                            <Typography type="body-sm">
                                                                                {found ? t(found.labelKey) : t("jobs.post.position.workModeNone")}
                                                                            </Typography>
                                                                        )
                                                                    }}
                                                                </Select.Value>
                                                                <Select.Indicator />
                                                            </Select.Trigger>
                                                            <Select.Popover>
                                                                <ListBox.Root aria-label={t("jobs.post.position.workMode")}>
                                                                    <ListBox.Item id={NONE_KEY} textValue={t("jobs.post.position.workModeNone")}>
                                                                        {t("jobs.post.position.workModeNone")}
                                                                    </ListBox.Item>
                                                                    {WORK_MODE_OPTIONS.map((option) => (
                                                                        <ListBox.Item key={option.value} id={option.value} textValue={t(option.labelKey)}>
                                                                            {t(option.labelKey)}
                                                                        </ListBox.Item>
                                                                    ))}
                                                                </ListBox.Root>
                                                            </Select.Popover>
                                                        </Select.Root>
                                                    ),
                                                ]} />
                                        ),
                                    },
                                ]} />
                        ),

                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-location">{t("jobs.post.position.location")}</Label>
                                <Input
                                    id="job-post-location"
                                    placeholder={t("jobs.post.position.locationPlaceholder")}
                                    maxLength={LOCATION_MAX}
                                    value={location}
                                    onChange={(event) => setValue("location", event.target.value)}
                                />
                            </TextField>
                        ),

                        () => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <Grid columns={{ base: 1, sm: 2 }} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                {
                                                    key: "salary-min",
                                                    content: () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-salary-min">{t("jobs.post.position.salaryMin")}</Label>
                                                            <Input
                                                                id="job-post-salary-min"
                                                                type="number"
                                                                inputMode="numeric"
                                                                min={0}
                                                                placeholder={t("jobs.post.position.salaryPlaceholder")}
                                                                value={salaryMin}
                                                                onChange={(event) => setValue("salaryMin", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                },
                                                {
                                                    key: "salary-max",
                                                    content: () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-salary-max">{t("jobs.post.position.salaryMax")}</Label>
                                                            <Input
                                                                id="job-post-salary-max"
                                                                type="number"
                                                                inputMode="numeric"
                                                                min={0}
                                                                placeholder={t("jobs.post.position.salaryPlaceholder")}
                                                                value={salaryMax}
                                                                onChange={(event) => setValue("salaryMax", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                },
                                            ]} />
                                    ),
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("jobs.post.position.salaryHint")}
                                        </Typography>
                                    ),
                                ]} />
                        ),

                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-description">{t("jobs.post.position.description")}</Label>
                                <TextArea
                                    id="job-post-description"
                                    rows={6}
                                    placeholder={t("jobs.post.position.descriptionPlaceholder")}
                                    className="resize-none"
                                    value={description}
                                    onChange={(event) => setValue("description", event.target.value)}
                                />
                            </TextField>
                        ),

                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-requirements">{t("jobs.post.position.requirements")}</Label>
                                <TextArea
                                    id="job-post-requirements"
                                    rows={5}
                                    placeholder={t("jobs.post.position.requirementsPlaceholder")}
                                    className="resize-none"
                                    value={requirements}
                                    onChange={(event) => setValue("requirements", event.target.value)}
                                />
                            </TextField>
                        ),
                    ]} />
            )}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Button, Spinner, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CompanySection } from "./CompanySection"
import { PositionSection } from "./PositionSection"
import { ApplyMethodSection } from "./ApplyMethodSection"
import { SubmitSuccess } from "./SubmitSuccess"
import { useSubmitJobPostingForm } from "@/hooks/rhf/useSubmitJobPostingForm"
import { useAppSelector } from "@/redux/hooks"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link JobPostFormPage}. */
export type JobPostFormPageProps = Record<string, never>
/**
 * Public job-post form — `/jobs/post`. Any signed-in user can submit an opening;
 * it goes live immediately (no approval queue). Sections are grouped by MEANING
 * (company · position · how to apply), each an independent `LabeledCard` — not
 * one card per field. On success, replaces the form with a persistent
 * confirmation screen ({@link SubmitSuccess}) rather than a toast, since this is
 * a full page the viewer navigated to, not a modal.
 *
 * @param props - {@link JobPostFormPageProps}
 */
export const JobPostFormPage = () => {
    const t = useTranslations()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const [submittedJobId, setSubmittedJobId] = useState<string | null>(null)

    const {
        watch,
        setValue,
        onSubmit,
        formState: { isSubmitting },
    } = useSubmitJobPostingForm({
        onSuccess: (jobPostingId) => setSubmittedJobId(jobPostingId),
    })

    const companyId = watch("companyId")
    const companyLabel = watch("companyLabel")
    const newCompanyTitle = watch("newCompanyTitle")
    const newCompanyLogoUrl = watch("newCompanyLogoUrl")
    const newCompanyWebsiteUrl = watch("newCompanyWebsiteUrl")
    const title = watch("title")
    const employmentType = watch("employmentType")
    const workMode = watch("workMode")
    const location = watch("location")
    const salaryMin = watch("salaryMin")
    const salaryMax = watch("salaryMax")
    const description = watch("description")
    const requirements = watch("requirements")
    const applyMethod = watch("applyMethod")
    const applyUrl = watch("applyUrl")
    const applyEmail = watch("applyEmail")

    if (submittedJobId) {
        return <SubmitSuccess jobDisplayId={submittedJobId} />
    }

    if (!authenticated) {
        return (
            <Box principle="center-measure"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
                className={"mx-auto max-w-2xl p-6 py-16 text-center"}>
                <StackV gap={3} principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center" items={[
                        () => (
                            <Typography type="h5" weight="semibold" align="center">
                                {t("jobs.post.signedOut.title")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" align="center">
                                {t("jobs.post.signedOut.description")}
                            </Typography>
                        ),
                    ]} />
            </Box>
        )
    }

    return (
        <Box principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            className={"mx-auto max-w-2xl p-6"}>
            <StackV gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            title={t("jobs.post.title")}
                            description={t("jobs.post.description")}
                        />
                    ),
                    () => (
                        <form onSubmit={onSubmit}>
                            <StackV gap={6} principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => (
                                        <CompanySection
                                            companyId={companyId}
                                            companyLabel={companyLabel}
                                            newCompanyTitle={newCompanyTitle}
                                            newCompanyLogoUrl={newCompanyLogoUrl}
                                            newCompanyWebsiteUrl={newCompanyWebsiteUrl}
                                            setValue={setValue}
                                        />
                                    ),
                                    () => (
                                        <PositionSection
                                            title={title}
                                            employmentType={employmentType}
                                            workMode={workMode}
                                            location={location}
                                            salaryMin={salaryMin}
                                            salaryMax={salaryMax}
                                            description={description}
                                            requirements={requirements}
                                            setValue={setValue}
                                        />
                                    ),
                                    () => (
                                        <ApplyMethodSection
                                            applyMethod={applyMethod}
                                            applyUrl={applyUrl}
                                            applyEmail={applyEmail}
                                            setValue={setValue}
                                        />
                                    ),
                                    () => (
                                        <Button
                                            type="submit"
                                            variant="primary"
                                            size="lg"
                                            isDisabled={isSubmitting}
                                            isPending={isSubmitting}
                                        >
                                            {({ isPending }) => (
                                                <>
                                                    {isPending ? <Spinner color="current" size="sm" /> : null}
                                                    {t("jobs.post.submit")}
                                                </>
                                            )}
                                        </Button>
                                    ),
                                ]} />
                        </form>
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
    useRef,
} from "react"
import useSWR from "swr"
import Editor from "@monaco-editor/react"
import {
    Button,
    Tabs,
    Typography,
} from "@heroui/react"
import { ArrowCounterClockwiseIcon, PlayIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useTheme } from "next-themes"
import { useParams, useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AIProcessingText } from "@/components/blocks/learn/AIProcessingText"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { StatusChip, type StatusChipTone } from "@/components/blocks/chips/StatusChip"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { StatGridCard } from "@/components/composites/stats/StatGridCard"
import { IOExampleCard } from "@/components/blocks/code/IOExampleCard"
import { CodeConsole } from "@/components/blocks/code/CodeConsole"
import { TestCaseResultGrid, type TestCaseResult } from "@/components/blocks/code/TestCaseResultGrid"
import { PracticeProblemSkeleton } from "./PracticeProblemSkeleton"
import { queryCodingProblem } from "@/modules/api/graphql/queries/query-coding-problem"
import { queryCodingProblemHint } from "@/modules/api/graphql/queries/query-coding-problem-hint"
import { queryMyCodingSubmissions } from "@/modules/api/graphql/queries/query-my-coding-submissions"
import { mutateSubmitCodingSolution } from "@/modules/api/graphql/mutations/mutation-submit-coding-solution"
import { mutateRevealCodingSolution } from "@/modules/api/graphql/mutations/mutation-reveal-coding-solution"
import {
    CodingDifficulty,
    CodingLanguage,
    CodingVerdict,
    parsePerCaseResults,
    type CodingProblem,
    type CodingProblemSolution,
    type CodingSubmission,
} from "@/modules/api/graphql/queries/types/coding"
import { useJobNotificationsSocketIo } from "@/hooks/socketio/useJobNotificationsSocketIo"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { useAppSelector } from "@/redux/hooks"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"

/** Props for {@link PracticeProblemPage}. */
export type PracticeProblemPageProps = Record<string, never>

/** Seniority level i18n key per difficulty (easy=junior, medium=mid, hard=senior). */
const LEVEL_KEY: Record<CodingDifficulty, string> = {
    [CodingDifficulty.Easy]: "junior",
    [CodingDifficulty.Medium]: "mid",
    [CodingDifficulty.Hard]: "senior",
}

/** Difficulty → chip tone (mirrors the list-card difficulty palette). */
const DIFFICULTY_TONE: Record<CodingDifficulty, StatusChipTone> = {
    [CodingDifficulty.Easy]: "success",
    [CodingDifficulty.Medium]: "warning",
    [CodingDifficulty.Hard]: "danger",
}

/** Map a coding language to its Monaco editor language id. */
const MONACO_LANGUAGE: Record<CodingLanguage, string> = {
    [CodingLanguage.Python]: "python",
    [CodingLanguage.JavaScript]: "javascript",
    [CodingLanguage.TypeScript]: "typescript",
    [CodingLanguage.Java]: "java",
    [CodingLanguage.Cpp]: "cpp",
}

/** Chip tone per verdict (accepted = success, terminal failures = danger). */
const VERDICT_TONE: Record<CodingVerdict, StatusChipTone> = {
    [CodingVerdict.Accepted]: "success",
    [CodingVerdict.WrongAnswer]: "danger",
    [CodingVerdict.TimeLimitExceeded]: "danger",
    [CodingVerdict.MemoryLimitExceeded]: "danger",
    [CodingVerdict.RuntimeError]: "danger",
    [CodingVerdict.CompileError]: "danger",
    [CodingVerdict.InternalError]: "warning",
    [CodingVerdict.Pending]: "neutral",
    [CodingVerdict.Judging]: "neutral",
}

/** Left-pane tab ids. */
type LeftTab = "description" | "solution" | "submissions"
/** Console (right-pane bottom) tab ids. */
type ConsoleTab = "testcase" | "result"

/** Terminal job statuses — judging has finished (success or failure). */
const isTerminalStatus = (status: JobStatus | undefined): boolean =>
    status === JobStatus.Completed || status === JobStatus.Failed

/**
 * Coding-problem detail + editor — a full-bleed 2-pane IDE (`/practice/[slug]`).
 * LEFT = tabbed reading column (`ExtendedTabs`: Description / Solution / Submissions);
 * RIGHT = Monaco editor over a `CodeConsole` (Test case / Result) whose result
 * tab renders the judged PER-CASE outcome (`TestCaseResultGrid` off the API's
 * `perCaseResults`) plus runtime/memory stats. The submit → async-judge →
 * realtime-verdict flow (SWR + `/job_notifications` socket + anti-cheat
 * telemetry) is unchanged from the prior build; only the shell is new.
 */
export const PracticeProblemPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const params = useParams()
    const slug = String(params.slug ?? "")
    const { theme } = useTheme()
    const socket = useJobNotificationsSocketIo()

    const [language, setLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [code, setCode] = useState<string>("")
    const [pendingJobId, setPendingJobId] = useState<string | null>(null)
    const [submitting, setSubmitting] = useState(false)
    const [leftTab, setLeftTab] = useState<LeftTab>("description")
    const [consoleTab, setConsoleTab] = useState<ConsoleTab>("testcase")
    // Live job status mirrored from Redux — the global /job_notifications lifecycle
    // dispatches every subscribed job's status into socketIo.jobStatusByJobId, the same
    // single source the challenge panel reads (no per-component EventEmitter listener).
    const pendingJobMessage = useAppSelector((state) =>
        (pendingJobId ? state.socketIo.jobStatusByJobId[pendingJobId] : undefined))
    const pendingJobStatus = pendingJobMessage?.data?.status
    const pendingJobError = pendingJobMessage?.data?.error
    const [showHint, setShowHint] = useState(false)
    const [showSolution, setShowSolution] = useState(false)
    // reference solutions arrive ONLY from the gated reveal mutation (never the
    // problem detail read) — held here once the learner reveals them
    const [revealedSolutions, setRevealedSolutions] = useState<Array<CodingProblemSolution>>([])
    const [solutionLanguage, setSolutionLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [touchedLanguages, setTouchedLanguages] = useState<Set<CodingLanguage>>(new Set())

    const telemetryRef = useRef({
        pasteCount: 0,
        pasteSizeMax: 0,
        keystrokeCount: 0,
        tabBlurCount: 0,
        timeOpen: Date.now(),
    })

    // Reset telemetry when the slug changes (user selects a new problem)
    useEffect(() => {
        telemetryRef.current = {
            pasteCount: 0,
            pasteSizeMax: 0,
            keystrokeCount: 0,
            tabBlurCount: 0,
            timeOpen: Date.now(),
        }
    }, [slug])

    // Track when window loses focus (user switching browser tabs/windows)
    useEffect(() => {
        const onBlur = () => {
            telemetryRef.current.tabBlurCount += 1
        }
        window.addEventListener("blur", onBlur)
        return () => window.removeEventListener("blur", onBlur)
    }, [])

    const {
        data: problem,
        isLoading,
        error: problemError,
        mutate: mutateProblem,
    } = useSWR<CodingProblem | null>(
        ["coding-problem", slug],
        async () => {
            const response = await queryCodingProblem({ request: { slug } })
            return response.data?.codingProblem.data ?? null
        },
    )

    const { data: hint } = useSWR<string | null>(
        ["coding-problem-hint", slug],
        async () => {
            const response = await queryCodingProblemHint({ request: { slug } })
            return response.data?.codingProblemHint.data?.hint ?? null
        },
    )

    const { data: submissionsData, mutate: mutateSubmissions } = useSWR(
        ["my-coding-submissions", slug],
        async () => {
            const response = await queryMyCodingSubmissions({
                request: { slug, page: 1, limit: 20 },
            })
            return response.data?.myCodingSubmissions.data ?? null
        },
    )

    const starterByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        problem?.starterCodes?.forEach((starter) => map.set(starter.language, starter.code))
        return map
    }, [problem?.starterCodes])

    const languages = useMemo<Array<CodingLanguage>>(() => {
        const withStarter = problem?.starterCodes?.map((starter) => starter.language) ?? []
        return withStarter.length > 0 ? withStarter : Object.values(CodingLanguage)
    }, [problem?.starterCodes])

    useEffect(() => {
        if (languages.length > 0 && !languages.includes(language)) {
            setLanguage(languages[0])
        }
    }, [languages, language])

    useEffect(() => {
        if (!touchedLanguages.has(language)) {
            setCode(starterByLanguage.get(language) ?? "")
        }
    }, [language, starterByLanguage, touchedLanguages])

    const latestSubmission = useMemo<CodingSubmission | undefined>(
        () => submissionsData?.submissions[0],
        [submissionsData?.submissions],
    )

    // decode the judged per-case outcome (input/expected/got for samples) — the
    // data the API always returned but the old UI threw away.
    const resultCases = useMemo<Array<TestCaseResult>>(
        () => parsePerCaseResults(latestSubmission?.perCaseResults ?? null).map((perCase) => ({
            key: String(perCase.orderIndex),
            label: t("codingPractice.caseLabel", { index: perCase.orderIndex }),
            passed: perCase.verdict === CodingVerdict.Accepted,
            isSample: perCase.isSample,
            input: perCase.input,
            expectedOutput: perCase.expectedOutput,
            got: perCase.stdout,
        })),
        [latestSubmission?.perCaseResults, t],
    )

    // reference solution code keyed by language (revealed in the "answer" panel)
    const solutionByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        revealedSolutions.forEach((solution) => map.set(solution.language, solution.code))
        return map
    }, [revealedSolutions])

    // languages that actually ship a reference solution
    const solutionLanguages = useMemo<Array<CodingLanguage>>(
        () => revealedSolutions.map((solution) => solution.language),
        [revealedSolutions],
    )

    // keep the solution language switcher pinned to an available language
    useEffect(() => {
        if (solutionLanguages.length > 0 && !solutionLanguages.includes(solutionLanguage)) {
            setSolutionLanguage(solutionLanguages[0])
        }
    }, [solutionLanguages, solutionLanguage])

    /** Back to the practice catalog. */
    const onBack = useCallback(
        () => router.push(pathConfig().locale(locale).practice().build()),
        [router, locale],
    )

    /** Reset the editor to the language's starter code (drops local edits). */
    const onResetCode = useCallback(() => {
        setCode(starterByLanguage.get(language) ?? "")
        setTouchedLanguages((prev) => {
            const next = new Set(prev)
            next.delete(language)
            return next
        })
    }, [language, starterByLanguage])

    // toggle the answer panel; revealing it forfeits the problem's points, so
    // confirm first and record the reveal server-side (best-effort)
    const onToggleSolution = useCallback(async () => {
        if (showSolution) {
            setShowSolution(false)
            return
        }
        if (!window.confirm(t("codingPractice.revealConfirm"))) {
            return
        }
        try {
            // the gated reveal mutation both records the forfeit AND returns the
            // reference solutions — the only path by which they reach the client
            const response = await mutateRevealCodingSolution({ request: { slug } })
            setRevealedSolutions(response.data?.revealCodingSolution.data?.solutions ?? [])
            setShowSolution(true)
        } catch {
            // reveal failed (network/auth) — keep the answer panel closed
        }
    }, [showSolution, slug, t])

    const onSubmit = useCallback(async () => {
        setSubmitting(true)
        setConsoleTab("result")
        try {
            const timeOpenToSubmitMs = Date.now() - telemetryRef.current.timeOpen
            const response = await mutateSubmitCodingSolution({
                request: {
                    slug,
                    language,
                    sourceCode: code,
                    telemetry: {
                        pasteCount: telemetryRef.current.pasteCount,
                        pasteSizeMax: telemetryRef.current.pasteSizeMax,
                        keystrokeCount: telemetryRef.current.keystrokeCount,
                        tabBlurCount: telemetryRef.current.tabBlurCount,
                        timeOpenToSubmitMs,
                    },
                },
            })
            const jobId = response.data?.submitCodingSolution.data?.jobId
            if (!jobId) return
            // Subscribe to the job room BEFORE the refetch so an early socket push is
            // never missed (race-free, like challenge). Status comes from Redux.
            setPendingJobId(jobId)
            socket.emit(PublicationEvent.SubscribeJobNotification, {
                data: { jobId },
                locale,
            })
            void mutateSubmissions()
        } finally {
            setSubmitting(false)
        }
    }, [slug, language, code, mutateSubmissions, socket, locale])

    // When the watched job reaches a terminal status (from Redux), refetch the
    // submissions (verdict now persisted) and stop watching.
    useEffect(() => {
        if (pendingJobId && isTerminalStatus(pendingJobStatus)) {
            void mutateSubmissions()
            setPendingJobId(null)
        }
    }, [pendingJobId, pendingJobStatus, mutateSubmissions])

    const judging = pendingJobId !== null

    // first load in flight → skeleton
    if (isLoading) {
        return <PracticeProblemSkeleton />
    }

    // load resolved with no problem: either a network/GraphQL error (`problemError`)
    // or the BE's uniform 404 for an unknown/disabled slug (fetcher yields `null`).
    // Distinguish the two, and never leave the skeleton spinning forever.
    if (!problem) {
        return (
            <div className="flex h-[calc(100vh-4rem)] flex-col">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <BackLink target={t("codingPractice.title")} onPress={onBack} />
                </Box>
                <Box principle="page-pad" className="flex min-h-0 flex-1 items-center justify-center px-6"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {problemError ? (
                        <AsyncContentError
                            title={t("codingPractice.detailError")}
                            description={t("codingPractice.detailErrorHint")}
                            onRetry={() => { void mutateProblem() }}
                            retryLabel={t("common.retry")}
                        />
                    ) : (
                        <EmptyState
                            icon={MagnifyingGlassIcon}
                            title={t("codingPractice.notFound")}
                            description={t("codingPractice.notFoundHint")}
                            action={() => (
                                <Button variant="primary" size="sm" onPress={onBack}>
                                    {t("codingPractice.backToPractice")}
                                </Button>
                            )}
                        />
                    )}
                </Box>
            </div>
        )
    }

    const samples = problem.testcases ?? []
    const memoryMb = problem.memoryLimitKb ? Math.round(problem.memoryLimitKb / 1024) : null

    /** LEFT: problem statement, samples, hint. */
    const descriptionPanel = (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <Typography type="h4" weight="bold">{problem.title}</Typography>,
                                        () => (
                                            <StatusChip tone={DIFFICULTY_TONE[problem.difficulty]}>
                                                {t(`codingPractice.level.${LEVEL_KEY[problem.difficulty]}`)}
                                            </StatusChip>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted">
                                    <span>{t("codingPractice.points", { points: problem.points })}</span>
                                    {problem.timeLimitMs ? <span>· {t("codingPractice.timeLimit", { ms: problem.timeLimitMs })}</span> : null}
                                    {memoryMb ? <span>· {t("codingPractice.memoryLimit", { mb: memoryMb })}</span> : null}
                                    {problem.tags.map((tag) => <span key={tag}>· {tag}</span>)}
                                </div>
                            ),
                        ]} />
                ),
                () => <MarkdownContent markdown={problem.statement ?? ""} />,
                ...(samples.length > 0 ? [
                    () => (
                        <StackV gap={4} principle="card-caption"
                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                            items={[
                                () => <hr className="border-default" />,
                                () => <p className="font-semibold">{t("codingPractice.samples")}</p>,
                                ...samples.map((testcase, index) => () => (
                                    <IOExampleCard
                                        key={testcase.id}
                                        rows={[
                                            { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                                            { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                                        ]}
                                    />
                                )),
                            ]} />
                    ),
                ] : []),
                ...(hint ? [
                    () => (
                        <StackV gap={4} principle="card-caption"
                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                            items={[
                                () => <hr className="border-default" />,
                                () => (
                                    <StackH gap={3} principle="flex-action" justify="between"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        items={[
                                            () => <p className="font-semibold">{t("codingPractice.hintTitle")}</p>,
                                            () => (
                                                <Button size="sm" variant="secondary" onPress={() => setShowHint((prev) => !prev)}>
                                                    {showHint ? t("codingPractice.hideHint") : t("codingPractice.showHint")}
                                                </Button>
                                            ),
                                        ]} />
                                ),
                                ...(showHint ? [() => <MarkdownContent markdown={hint} />] : []),
                            ]} />
                    ),
                ] : []),
            ]} />
    )

    /** LEFT: reveal-gated reference solution, one tab per language. */
    const solutionPanel = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <StackH gap={3} principle="flex-action" justify="between"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => <p className="font-semibold">{t("codingPractice.solutionTitle")}</p>,
                            () => (
                                <Button size="sm" variant="secondary" onPress={onToggleSolution}>
                                    {showSolution ? t("codingPractice.hideSolution") : t("codingPractice.showSolution")}
                                </Button>
                            ),
                        ]} />
                ),
                () => showSolution && solutionLanguages.length > 0 ? (
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <Cluster gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." items={solutionLanguages.map((option) => () => (
                                    <Button
                                        key={option}
                                        size="sm"
                                        variant={solutionLanguage === option ? "primary" : "secondary"}
                                        onPress={() => setSolutionLanguage(option)}
                                    >
                                        {t(`codingPractice.language.${option}`)}
                                    </Button>
                                ))} />
                            ),
                            () => (
                                <MarkdownContent
                                    markdown={`\`\`\`${MONACO_LANGUAGE[solutionLanguage]}\n${
                                        solutionByLanguage.get(solutionLanguage) ?? ""
                                    }\n\`\`\``}
                                />
                            ),
                        ]} />
                ) : (
                    <Typography type="body-sm" color="muted">
                        {t("codingPractice.solutionLocked")}
                    </Typography>
                ),
            ]} />
    )

    /** LEFT: the learner's prior submissions for this problem. */
    const submissionItems: Array<SurfaceCardListItem> = (submissionsData?.submissions ?? []).map(
        (submission: CodingSubmission) => ({
            key: submission.id,
            title: new Date(submission.createdAt).toLocaleString(),
            meta: () => (
                <>
                    <Typography type="body-xs" color="muted">
                        {t(`codingPractice.language.${submission.language}`)}
                    </Typography>
                    <StatusChip tone={VERDICT_TONE[submission.verdict]}>
                        {t(`codingPractice.verdict.${submission.verdict}`)}
                    </StatusChip>
                </>
            ),
        }),
    )
    const submissionsPanel = submissionItems.length > 0 ? (
        <SurfaceCardList items={submissionItems} />
    ) : (
        <EmptyState title={t("codingPractice.historyEmpty")} />
    )

    /** CONSOLE: sample testcases (pre-run reference). */
    const testcaseTab = samples.length > 0 ? (
        <StackV gap={4} principle="card-caption" explain="Holds caption text under card media so the caption stays attached to the image above it." items={samples.map((testcase, index) => () => (
            <IOExampleCard
                key={testcase.id}
                rows={[
                    { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                    { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                ]}
            />
        ))} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.noSamples")}</Typography>
    )

    /** CONSOLE: live judging / verdict + per-case grid + stats. */
    const resultTab = judging && pendingJobStatus ? (
        <AIProcessingText
            jobCategory={JobCategory.JudgeCoding}
            jobStatus={pendingJobStatus}
            error={pendingJobError}
        />
    ) : latestSubmission ? (
        <StackV gap={5} principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                () => (
                    <Cluster gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => (
                                <StatusChip tone={VERDICT_TONE[latestSubmission.verdict]}>
                                    {t(`codingPractice.verdict.${latestSubmission.verdict}`)}
                                </StatusChip>
                            ),
                            () => (
                                <Typography type="body-sm" color="muted">
                                    {t("codingPractice.passed")}: {latestSubmission.passedCount}/{latestSubmission.totalCount}
                                </Typography>
                            ),
                        ]} />
                ),
                () => (
                    <StatGridCard
                        items={[
                            {
                                key: "passed",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.passedCount}/{latestSubmission.totalCount}</span>
                                        <span className="text-xs text-muted">{t("codingPractice.statPassed")}</span>
                                    </div>
                                ),
                            },
                            {
                                key: "runtime",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.runtimeMs ?? "—"}<span className="text-xs"> ms</span></span>
                                        <span className="text-xs text-muted">{t("codingPractice.statRuntime")}</span>
                                    </div>
                                ),
                            },
                            {
                                key: "memory",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.memoryKb ?? "—"}<span className="text-xs"> KB</span></span>
                                        <span className="text-xs text-muted">{t("codingPractice.statMemory")}</span>
                                    </div>
                                ),
                            },
                        ]}
                    />
                ),
                ...(resultCases.length > 0 ? [
                    () => (
                        <TestCaseResultGrid
                            cases={resultCases}
                            labels={{
                                input: t("codingPractice.input"),
                                expected: t("codingPractice.expected"),
                                got: t("codingPractice.got"),
                                hidden: t("codingPractice.hiddenCase"),
                            }}
                        />
                    ),
                ] : []),
                ...(latestSubmission.compileOutput ? [
                    () => (
                        <pre data-principle="cell-pad" className="whitespace-pre-wrap rounded-2xl bg-danger-soft p-3 text-xs text-danger-soft-foreground">
                            {latestSubmission.compileOutput}
                        </pre>
                    ),
                ] : []),
            ]} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.resultEmpty")}</Typography>
    )

    return (
        // full-bleed 2-pane IDE: left reading column | right editor + console
        <div className="grid h-[calc(100vh-4rem)] grid-cols-1 @app-lg:grid-cols-2">

            {/* ── LEFT: tabbed reading column ── */}
            <div className="flex min-h-0 flex-col overflow-hidden border-r border-default">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => <BackLink target={t("codingPractice.title")} onPress={onBack} />,
                            () => (
                                <ExtendedTabs
                                    selectedKey={leftTab}
                                    onSelectionChange={(key) => setLeftTab(key as LeftTab)}
                                >
                                    <Tabs.ListContainer>
                                        <Tabs.List aria-label={problem.title}>
                                            <Tabs.Tab id="description">
                                                {t("codingPractice.tabDescription")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                            <Tabs.Tab id="solution">
                                                {t("codingPractice.tabSolution")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                            <Tabs.Tab id="submissions">
                                                {t("codingPractice.tabSubmissions")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                        </Tabs.List>
                                    </Tabs.ListContainer>
                                </ExtendedTabs>
                            ),
                        ]} />
                </Box>
                <Box principle="page-pad" className="min-h-0 flex-1 overflow-auto px-6 py-5"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {leftTab === "description" && descriptionPanel}
                    {leftTab === "solution" && solutionPanel}
                    {leftTab === "submissions" && submissionsPanel}
                </Box>
            </div>

            {/* ── RIGHT: editor + console ── */}
            <div className="flex min-h-0 flex-col overflow-hidden">
                {/* language selector + reset */}
                <Box principle="pill-pad" className="flex flex-wrap items-center justify-between border-b border-default px-4 py-2"
                    explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                    <Cluster gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." items={languages.map((option) => () => (
                        <Button
                            key={option}
                            size="sm"
                            variant={language === option ? "primary" : "secondary"}
                            onPress={() => setLanguage(option)}
                        >
                            {t(`codingPractice.language.${option}`)}
                        </Button>
                    ))} />
                    <Button size="sm" variant="tertiary" onPress={onResetCode}>
                        <ArrowCounterClockwiseIcon className="size-4" aria-hidden focusable="false" />
                        {t("codingPractice.resetCode")}
                    </Button>
                </Box>

                {/* Monaco editor */}
                <div className="min-h-0 flex-1">
                    <Editor
                        height="100%"
                        language={MONACO_LANGUAGE[language]}
                        theme={theme === "dark" ? "vs-dark" : "light"}
                        value={code}
                        onChange={(value) => {
                            setCode(value ?? "")
                            setTouchedLanguages((prev) => new Set(prev).add(language))
                        }}
                        onMount={(editor) => {
                            editor.getDomNode()?.querySelector("textarea")?.setAttribute("spellcheck", "false")
                            editor.onDidPaste((e) => {
                                const model = editor.getModel()
                                const pastedText = model ? model.getValueInRange(e.range) : ""
                                const size = pastedText.length
                                telemetryRef.current.pasteCount += 1
                                telemetryRef.current.pasteSizeMax = Math.max(
                                    telemetryRef.current.pasteSizeMax,
                                    size
                                )
                            })
                            editor.onKeyDown(() => {
                                telemetryRef.current.keystrokeCount += 1
                            })
                            editor.onDidBlurEditorText(() => {
                                telemetryRef.current.tabBlurCount += 1
                            })
                        }}
                        options={{
                            minimap: { enabled: false },
                            fontSize: 14,
                            scrollBeyondLastLine: false,
                            padding: { top: 12, bottom: 12 },
                            bracketPairColorization: { enabled: true },
                            cursorBlinking: "smooth",
                            smoothScrolling: true,
                        }}
                    />
                </div>

                {/* bottom console — Test case / Result + Run/Submit bar */}
                <CodeConsole
                    className="h-[42%]"
                    ariaLabel={t("codingPractice.consoleLabel")}
                    selectedTab={consoleTab}
                    onSelectTab={(key) => setConsoleTab(key as ConsoleTab)}
                    tabs={[
                        { key: "testcase", label: t("codingPractice.tabTestcase"), content: testcaseTab },
                        { key: "result", label: t("codingPractice.tabResult"), content: resultTab },
                    ]}
                    hint={t("codingPractice.runVsSubmit")}
                    actions={(
                        <>
                            {/* "Run on sample" needs a dedicated judge-sample endpoint on the BE —
                                doesn't exist yet, so it's left disabled (the console hint explains it) instead of silently dropping it. */}
                            <Button
                                size="sm"
                                variant="secondary"
                                isDisabled
                            >
                                <PlayIcon className="size-4" aria-hidden focusable="false" />
                                {t("codingPractice.run")}
                            </Button>
                            <Button
                                size="sm"
                                variant="primary"
                                isPending={submitting || judging}
                                isDisabled={code.trim().length === 0}
                                onPress={onSubmit}
                            >
                                {judging ? t("codingPractice.judging") : t("codingPractice.submit")}
                            </Button>
                        </>
                    )}
                />
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { buildDifficultySegments } from "@/modules/utils/challenge-difficulty"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { StatPair } from "@/components/composites/stats/StatPair"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { SkeletonProps } from "@/components/frames/_slot"
import { StackV } from "@/components/frames/Stack"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link OverviewChallengeSkills}. */
export interface OverviewChallengeSkillsProps {
    /** Section label, rendered outside the card (owned here, like every other self-contained section). */
    label: string
    /** Optional "see more" link on the label row. */
    onSeeMore?: () => void
    /** Text for the see-more link. */
    seeMoreLabel?: string
    /** Stretch the section (and its card) to fill the row's height. */
    fillHeight?: boolean
}

/**
 * Overview snapshot — skills proven by graded CHALLENGES, mirroring the "Skills
 * via Practice" card: a passed-count headline, the 4-tone DIFFICULTY
 * {@link SegmentBar}, then a language {@link SegmentBar} (brand legend, same as the
 * Challenges tab). A teaser only — the full submission list lives behind "See
 * more" in the Challenges tab. One labeled {@link SurfaceCardList} owns the
 * section header, empty/error, and `isSkeleton` (B37 class C collapse — no outer
 * `LabeledCard` frameless shell).
 *
 * @param props - {@link OverviewChallengeSkillsProps}
 */
export const OverviewChallengeSkills = ({ label, onSeeMore, seeMoreLabel, fillHeight }: OverviewChallengeSkillsProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const { data, isLoading, error, mutate } = useQueryUserSolvedChallengesSwr(userId)

    const challenges = data ?? []
    // difficulty distribution across all passed challenges
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language (V1-legacy)
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    const isFirstLoad = (isLoading || !userId) && challenges.length === 0
    const showError = challenges.length === 0 && Boolean(error)

    const snapshotItems: Array<SurfaceCardListItem> = [{
        key: "snapshot",
        content: ({ isSkeleton: rowSkeleton }: SkeletonProps) => {
            const shimmer = rowSkeleton ?? isFirstLoad
            return (
                <StackV gap={4} items={[
                    () => (
                        shimmer
                            ? <StatPair isSkeleton />
                            : (
                                <StatPair
                                    value={String(challenges.length)}
                                    label={t("publicProfile.challengesCount")}
                                />
                            )
                    ),
                    ...(shimmer || difficultySegments.length > 0
                        ? [() => (
                            shimmer
                                ? (
                                    <SegmentBar
                                        isSkeleton
                                        ariaLabel={`${challenges.length} ${t("publicProfile.challengesCount")}`}
                                    />
                                )
                                : (
                                    <SegmentBar
                                        ariaLabel={`${challenges.length} ${t("publicProfile.challengesCount")}`}
                                        segments={difficultySegments}
                                    />
                                )
                        )]
                        : []),
                    ...(shimmer || langs.length > 0
                        ? [() => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("publicProfile.skillsSnapshot.languagesLabel")}
                                        </Typography>
                                    ),
                                    () => (
                                        shimmer
                                            ? (
                                                <SegmentBar
                                                    isSkeleton
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                />
                                            )
                                            : (
                                                <SegmentBar
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                    segments={langs.map(([lang, count]) => ({
                                                        key: lang,
                                                        label: getLanguageLabel(lang),
                                                        value: count,
                                                        color: getLanguageColor(lang),
                                                    }))}
                                                />
                                            )
                                    ),
                                ]} />
                        )]
                        : []),
                ]} />
            )
        },
    }]

    return (
        <SurfaceCardList
            label={label}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            fillHeight={fillHeight}
            isSkeleton={isFirstLoad}
            error={showError ? error : undefined}
            errorState={() => (
                <AsyncContentError
                    title={t("publicProfile.loadError")}
                    onRetry={() => { void mutate() }}
                    retryLabel={t("publicProfile.loadErrorRetry")}
                />
            )}
            emptyState={() => (
                <AsyncContentEmpty title={t("publicProfile.skills.empty")} />
            )}
            items={isFirstLoad || challenges.length > 0 ? snapshotItems : []}
        />
    )
}

"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { StatPair } from "@/components/composites/stats/StatPair"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { SkeletonProps } from "@/components/frames/_slot"
import { StackV } from "@/components/frames/Stack"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link OverviewCodeSkills}. */
export interface OverviewCodeSkillsProps {
    /** Section label, rendered outside the card (owned here, like every other self-contained section). */
    label: string
    /** Optional "see more" link on the label row. */
    onSeeMore?: () => void
    /** Text for the see-more link. */
    seeMoreLabel?: string
    /** Stretch the section (and its card) to fill the row's height. */
    fillHeight?: boolean
}

/** Capitalize the first character of a key for display. */
const capitalizeKey = (key: string): string =>
    key.charAt(0).toUpperCase() + key.slice(1)

/** Slice colour per difficulty bucket (semantic). */
const DIFF_COLOR: Record<string, string> = {
    easy: "var(--success)",
    medium: "var(--warning)",
    hard: "var(--danger)",
}

/**
 * Overview content — skills proven by solving CODE PROBLEMS (the practice judge):
 * total solved + difficulty depth chips + top-language chips with real counts.
 * One labeled {@link SurfaceCardList} owns the section header, empty/error, and
 * `isSkeleton` (B37 class C collapse — no outer `LabeledCard` frameless shell).
 * Counts are real, never relative-to-max, so 2 solves never looks like mastery.
 *
 * @param props - {@link OverviewCodeSkillsProps}
 */
export const OverviewCodeSkills = ({ label, onSeeMore, seeMoreLabel, fillHeight }: OverviewCodeSkillsProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const { data, isLoading, error, mutate } = useQueryUserCodingSkillsSwr(userId)

    const byLanguage = data?.byLanguage ?? []
    const byDifficulty = data?.byDifficulty ?? []
    const totalSolved = byDifficulty.reduce((acc, d) => acc + d.solved, 0)
        || byLanguage.reduce((acc, l) => acc + l.solved, 0)
    const orderedLanguages = [...byLanguage].sort((a, b) => b.solved - a.solved)
    const isFirstLoad = (isLoading || !userId) && totalSolved === 0 && !data
    const showError = !data && error

    /** Localized label for a difficulty bucket; falls back to the capitalized key. */
    const diffLabel = (key: string): string => {
        const labels: Record<string, string> = {
            easy: t("publicProfile.skillsSnapshot.diffEasy"),
            medium: t("publicProfile.skillsSnapshot.diffMedium"),
            hard: t("publicProfile.skillsSnapshot.diffHard"),
        }
        return labels[key] ?? capitalizeKey(key)
    }

    const snapshotItems: Array<SurfaceCardListItem> = [{
        key: "snapshot",
        content: ({ isSkeleton: rowSkeleton }: SkeletonProps) => {
            const shimmer = rowSkeleton ?? isFirstLoad
            return (
                <StackV gap={4} items={[
                    () => (
                        shimmer
                            ? <StatPair isSkeleton />
                            : (
                                <StatPair
                                    value={String(totalSolved)}
                                    label={t("publicProfile.skillsSnapshot.solvedLabel")}
                                />
                            )
                    ),
                    () => (
                        shimmer
                            ? (
                                <SegmentBar
                                    isSkeleton
                                    ariaLabel={`${totalSolved} ${t("publicProfile.skillsSnapshot.solvedLabel")}`}
                                />
                            )
                            : (
                                <SegmentBar
                                    ariaLabel={`${totalSolved} ${t("publicProfile.skillsSnapshot.solvedLabel")}`}
                                    segments={byDifficulty.map((d) => ({
                                        key: d.key,
                                        label: diffLabel(d.key),
                                        value: d.solved,
                                        color: DIFF_COLOR[d.key],
                                    }))}
                                />
                            )
                    ),
                    ...(shimmer || orderedLanguages.length > 0
                        ? [() => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("publicProfile.skillsSnapshot.languagesLabel")}
                                        </Typography>
                                    ),
                                    () => (
                                        shimmer
                                            ? (
                                                <SegmentBar
                                                    isSkeleton
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                />
                                            )
                                            : (
                                                <SegmentBar
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                    segments={orderedLanguages.map((lang) => ({
                                                        key: lang.key,
                                                        label: getLanguageLabel(lang.key),
                                                        value: lang.solved,
                                                        color: getLanguageColor(lang.key),
                                                    }))}
                                                />
                                            )
                                    ),
                                ]} />
                        )]
                        : []),
                ]} />
            )
        },
    }]

    return (
        <SurfaceCardList
            label={label}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            fillHeight={fillHeight}
            isSkeleton={isFirstLoad}
            error={showError ? error : undefined}
            errorState={() => (
                <AsyncContentError
                    title={t("publicProfile.loadError")}
                    onRetry={() => { void mutate() }}
                    retryLabel={t("publicProfile.loadErrorRetry")}
                />
            )}
            emptyState={() => (
                <AsyncContentEmpty
                    title={t("publicProfile.skills.empty")}
                    description={t("publicProfile.skills.emptyHint")}
                />
            )}
            items={isFirstLoad || totalSolved > 0 ? snapshotItems : []}
        />
    )
}

"use client"

import React, { useState } from "react"
import { FlameIcon as FireIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { ContributionCalendarView } from "@/components/blocks/profile/ContributionCalendarView"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useQueryUserContributionCalendarSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserContributionCalendarSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserWeeklyStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserWeeklyStatsSwr"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Overview content — the contribution heatmap (GitHub-style) + the streak line
 * (current / longest). Content only (no card): the parent `LabeledCard` supplies
 * the frame.
 *
 * The calendar owns its own resting state, so there is no placeholder copy of its
 * shape here — only the streak line, which belongs to this block, shimmers on its
 * own (`loading-and-skeleton.md`).
 */
export const OverviewContributions = () => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null

    const [year, setYear] = useState(() => new Date().getFullYear())
    const { data, isLoading, error, mutate } = useQueryUserContributionCalendarSwr(userId, year)
    const { data: weekly } = useQueryUserWeeklyStatsSwr(userId)

    const days = data ?? []
    // first load, nothing in hand: no user resolved yet, or the calendar still in flight
    const isSkeleton = (isLoading || !userId) && days.length === 0

    // error beats a stale loading flag — but only a settled failure with nothing cached.
    if (error && days.length === 0) {
        return (
            <AsyncContentError
                title={t("publicProfile.loadError")}
                onRetry={() => { void mutate() }}
                retryLabel={t("publicProfile.loadErrorRetry")}
            />
        )
    }

    // Hoist streak items so the outer calendar|streak column is scanned as
    // gap-only (no nested align/principle leaking into the opening tag).
    const streakItems = [
        () => (
            <FireIcon
                aria-hidden
                focusable="false"
                className="size-5 text-accent-soft-foreground"
            />
        ),
        () => (
            <Typography
                size="sm"
                weight="medium"
                isSkeleton={isSkeleton}
                text={t("profile.streakLine", {
                    streak: weekly?.streak ?? 0,
                    longest: weekly?.longestStreak ?? 0,
                })}
            />
        ),
    ]

    return (
        <StackV
            identity={{ tier: "block", component: "OverviewContributions" }}
            gap={4}
            principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <ContributionCalendarView
                        isSkeleton={isSkeleton}
                        days={days}
                        year={year}
                        onYearChange={setYear}
                    />
                ),
                // gap-only row: icon+text at house step 3 (8px); icon-text is step 2
                () => <StackH gap={3} items={streakItems} />,
            ]}
        />
    )
}

"use client"

import React from "react"
import { BookOpenIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useResolveRouteNavigation } from "@/components/blocks/entity/EntityToken/useResolveRouteNavigation"
import { CourseTrialChip } from "@/components/blocks/course/CourseTrialChip"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { CourseProgressBar } from "@/components/blocks/stats/CourseProgressBar"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"

/** One profile course-progress item (element of the `useQueryUserCoursesSwr` list). */
type CourseItem = NonNullable<ReturnType<typeof useQueryUserCoursesSwr>["data"]>[number]

/** Props for {@link CourseRow}. */
export interface CourseRowProps {
    /** One profile course-progress item. Absent only while {@link CourseRowProps.isSkeleton}. */
    item?: CourseItem
    /** Only the profile OWNER sees the "Trial" chip. */
    isOwnProfile?: boolean
    /**
     * First load, nothing in hand → this row shimmers in place. The resting state lives
     * HERE, beside the loaded one, so the two shapes cannot drift the way a placeholder
     * hand-kept in the list would (`loading-and-skeleton.md`).
     */
    isSkeleton?: boolean
}

/**
 * One profile course as a WHOLE-ROW clickable surface-list item — mirrors the
 * dashboard `MyCoursesProgress` CourseRow. Pressing anywhere resolves the course
 * route and navigates ({@link useResolveRouteNavigation} per row); the title
 * underlines on CARD hover with a foreground decoration — NOT a nested
 * `EntityToken`/`<Link>` (which hovers only on the label + draws an accent underline).
 *
 * @param props - {@link CourseRowProps}
 */
export const CourseRow = ({ item, isOwnProfile = false, isSkeleton = false }: CourseRowProps) => {
    const t = useTranslations()
    const { onPress, pending, routable } = useResolveRouteNavigation({ globalId: item?.globalId ?? "" })

    const dims = [
        { key: "content", completed: item?.contentCompleted ?? 0, total: item?.contentTotal ?? 0 },
        { key: "challenge", completed: item?.challengeCompleted ?? 0, total: item?.challengeTotal ?? 0 },
        { key: "milestone", completed: item?.completed ?? 0, total: item?.total ?? 0 },
    ]
    const totalTasks = dims.reduce((acc, d) => acc + d.total, 0)
    const doneTasks = dims.reduce((acc, d) => acc + d.completed, 0)
    const percent = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0

    const resting = isSkeleton || !item

    return (
        <SurfaceListCardItem
            onPress={resting ? undefined : onPress}
            isDisabled={resting || !routable || pending}
            hover="underline"
        >
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (resting
                        ? <Skeleton className="size-12 shrink-0 rounded-xl" />
                        : <IconTile size="sm" src={item.thumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />),
                    () => {
                        const titleRowItems = [
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    truncate
                                    underlineOnGroupHover
                                    isSkeleton={resting}
                                    classNames={resting ? ["w-1/2"] : ["min-w-0", "flex-1"]}
                                    text={item?.label}
                                />
                            ),
                            ...(!resting && isOwnProfile
                                ? [() => <CourseTrialChip isEnrolled={item.isEnrolled} />]
                                : []),
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    isSkeleton={resting}
                                    classNames={resting ? ["w-fit"] : undefined}
                                    text={`${percent}%`}
                                />
                            ),
                        ]
                        return (
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                classNames={["min-w-0", "flex-1"]}
                                items={[
                                    () => (
                                        <StackH
                                            gap={3}
                                            principle="flex-action"
                                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                            justify="between"
                                            items={titleRowItems}
                                        />
                                    ),
                                    () => (resting
                                        ? <Skeleton.ProgressBar />
                                        : (
                                            <CourseProgressBar
                                                ariaLabel={`${item.label} · ${percent}%`}
                                                dims={dims.map((d) => ({
                                                    ...d,
                                                    label: t(`dashboard.courseProgress.${d.key}`),
                                                }))}
                                            />
                                        )),
                                ]}
                            />
                        )
                    },
                ]}
            />
        </SurfaceListCardItem>
    )
}
